        onProgress?.(85);
        await ffmpeg.exec([
            "-i",
            "input.webm",
            "-c:v",
            "libx264",
            "-preset",
            "fast",
            "-crf",
            "23",
            "-c:a",
            "aac",
            "-b:a",
            "128k",
            "-movflags",
            "+faststart",
            "output.mp4"
        ]);
        onProgress?.(95);
